"""Output generation: client.py, README.md, map.json, evidence/."""
from __future__ import annotations

import json
import urllib.parse
from pathlib import Path

from .graph import build_graph
from .schema import fmt, to_openapi
from .util import class_name, now_iso

CLIENT_HEAD = '''#!/usr/bin/env python3
"""Generated by rea-web from {source} on {ts}.

Regenerate with: rea-web map {source}
"""
from __future__ import annotations

import json
import urllib.error
import urllib.parse
import urllib.request

DEFAULT_BASE_URL = {base!r}


class ApiError(Exception):
    """A non-2xx response from the API."""

    def __init__(self, status, body, url):
        super().__init__("HTTP {{}} for {{}}: {{}}".format(status, url, body[:300]))
        self.status = status
        self.body = body
        self.url = url


def _parse(content_type, raw):
    text = raw.decode("utf-8", "replace")
    if "json" in content_type:
        try:
            return json.loads(text)
        except ValueError:
            pass
    return text


class {cls}(object):
    """{title} client.

    `token` is sent as `Authorization: Bearer <token>`; other auth goes in `headers`.
    """

    def __init__(self, base_url=DEFAULT_BASE_URL, token=None, headers=None, timeout=30):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.headers = dict(headers or {{}})
        if token:
            self.headers["Authorization"] = "Bearer " + token

    def _request(self, method, path, *, path_params=None, query=None, body=None, headers=None, base_url=None):
        for key, value in (path_params or {{}}).items():
            path = path.replace("{{" + key + "}}", urllib.parse.quote(str(value), safe=""))
        url = (base_url or self.base_url).rstrip("/") + path
        clean = {{k: v for k, v in (query or {{}}).items() if v is not None}}
        if clean:
            url += "?" + urllib.parse.urlencode(clean, doseq=True)
        data = None
        sent = {{"Accept": "application/json"}}
        if body is not None:
            data = json.dumps(body).encode("utf-8")
            sent["Content-Type"] = "application/json"
        sent.update(self.headers)
        sent.update(headers or {{}})
        request = urllib.request.Request(url, data=data, headers=sent, method=method)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw = response.read()
                return _parse(response.headers.get("Content-Type", ""), raw)
        except urllib.error.HTTPError as exc:
            raise ApiError(exc.code, exc.read().decode("utf-8", "replace"), url) from None
'''


def _args(ep):
    """Return (path pairs, keyword args, body arg) with collision-free Python names."""
    path_pairs, kwargs = [], []
    used = set()
    reserved = {"self", "headers"}

    def unique(arg):
        arg = arg or "value"
        while arg in used or arg in reserved:
            arg += "_"
        used.add(arg)
        return arg

    for param in ep["params"]:
        if param["in"] == "path":
            path_pairs.append((param["name"], unique(param["arg"])))
    for param in ep["params"]:
        if param["in"] in ("query", "header"):
            kwargs.append((param, unique(param["arg"])))
    body_arg = unique("body") if ep.get("body") else None
    return path_pairs, kwargs, body_arg


def _docstring(ep):
    line = f"{ep['method']} {ep['path']}"
    if ep.get("summary"):
        line += f" — {ep['summary'].rstrip('.')}"
    refs = ", ".join(e["ref"] for e in ep.get("evidence", []))
    return f'        """{line}. Evidence: {refs}"""' if refs else f'        """{line}."""'


def _method(ep, default_base=""):
    if ep.get("kind") == "graphql":
        query = json.dumps((ep.get("graphql") or {}).get("query") or "")
        lines = [
            f"    def {ep['id']}(self, *, variables=None, headers=None):",
            _docstring(ep),
            f'        body = {{"query": {query}, "variables": variables or {{}}}}',
            "        return self._request(",
            f'            "{ep["method"]}",',
            f'            "{ep["path"]}",',
            "            body=body,",
            "            headers=headers,",
            ("            base_url=" + repr(ep["base_url"]) + ",") if ep.get("base_url") != default_base else "",
            "        )",
            "", "",
        ]
        return "\n".join(lines)
    path_pairs, kwargs, body_arg = _args(ep)
    signature = ["self"] + [arg for _, arg in path_pairs]
    signature.append("*")
    signature += [f"{arg}=None" for _, arg in kwargs]
    if body_arg:
        signature.append(f"{body_arg}=None")
    signature.append("headers=None")
    lines = [
        f"    def {ep['id']}({', '.join(signature)}):",
        _docstring(ep),
    ]
    headers = [(p, arg) for p, arg in kwargs if p["in"] == "header"]
    if headers:
        lines.append("        headers = dict(headers or {})")
        for param, arg in headers:
            lines += [f"        if {arg} is not None:", f'            headers["{param["name"]}"] = {arg}']
    lines += [
        "        return self._request(",
        f'            "{ep["method"]}",',
        f'            "{ep["path"]}",',
    ]
    if path_pairs:
        pairs = ", ".join(f'"{name}": {arg}' for name, arg in path_pairs)
        lines.append(f"            path_params={{{pairs}}},")
    query = [(p, arg) for p, arg in kwargs if p["in"] == "query"]
    if query:
        pairs = ", ".join(f'"{p["name"]}": {arg}' for p, arg in query)
        lines.append(f"            query={{{pairs}}},")
    if body_arg:
        lines.append(f"            body={body_arg},")
    lines += ["            headers=headers,"]
    if ep.get("base_url") and ep["base_url"] != default_base:
        lines.append(f'            base_url={ep["base_url"]!r},')
    lines += ["        )", "", ""]
    return "\n".join(lines)


def client_name(meta):
    title = (meta.get("title") or "").strip()
    if title and len(title) <= 45:
        return class_name(title)
    host = urllib.parse.urlsplit(meta.get("base_url") or "").netloc
    labels = [label for label in host.split(".") if label and label != "www" and not label.isdigit()]
    return class_name(labels[0] if labels else title or "Api")


def client_source(endpoints, meta):
    cls = client_name(meta) + "Client"
    parts = [
        CLIENT_HEAD.format(
            source=meta["source"],
            ts=meta["generated_at"],
            base=meta.get("base_url") or "",
            cls=cls,
            title=(meta.get("title") or "API").replace('"""', "'"),
        ),
        "",
    ]
    for endpoint in endpoints:
        if not endpoint.get("external") and endpoint.get("kind") != "websocket":
            parts.append(_method(endpoint, meta.get("base_url")))
    return "\n".join(parts).rstrip() + "\n"


def _sample(schema, depth=0):
    if not schema or depth > 2:
        return None
    kind = schema.get("type")
    if kind == "object":
        return {k: _sample(v, depth + 1) for k, v in schema.get("fields", {}).items()
                if k not in schema.get("optional", [])}
    if kind == "array":
        item = _sample(schema.get("items"), depth + 1)
        return [item] if item is not None else []
    return {"string": "", "integer": 0, "number": 0, "boolean": False}.get(kind)


def _example(ep):
    if ep.get("kind") == "graphql":
        variables = (ep.get("graphql") or {}).get("variables") or {}
        return f"api.{ep['id']}(variables={variables!r})"
    path_pairs, kwargs, body_arg = _args(ep)
    args = []
    for param in ep["params"]:
        if param["in"] == "path":
            args.append(f'"{param["name"]}"')
    for param, arg in kwargs:
        if param.get("example") is not None:
            args.append(f"{arg}={param['example']!r}")
    if body_arg:
        args.append(f"{body_arg}={_sample(ep['body'].get('schema'))!r}")
    return f"api.{ep['id']}({', '.join(args)})"


def _param_table(ep):
    if not ep["params"]:
        return ""
    rows = ["| param | in | type | required | example |", "|---|---|---|---|---|"]
    for p in ep["params"]:
        example = "" if p.get("example") is None else f"`{p['example']}`"
        rows.append(f"| `{p['name']}` | {p['in']} | {p['type']} | {'yes' if p['required'] else 'no'} | {example} |")
    return "\n".join(rows)


def _endpoint_meta(ep):
    bits = []
    if ep.get("auth"):
        auth = ep["auth"]
        detail = ep.get("auth_detail") or {}
        if detail.get("ttl_seconds") is not None:
            auth += f" (JWT expires in ~{detail['ttl_seconds']}s)"
        bits.append(f"auth: {auth}")
    observed = ep.get("observed") or {}
    if observed:
        bits.append(f"observed {observed.get('count')}x, statuses {', '.join(map(str, observed.get('statuses', [])))}")
    pagination = ep.get("pagination")
    if pagination:
        bits.append("pagination: " + ", ".join(pagination.get("params") or pagination.get("response_fields")))
    if ep.get("rate_limit"):
        bits.append("rate-limit headers: " + ", ".join(ep["rate_limit"]))
    return " · ".join(bits)


def _site_section(site):
    signals = site.get("signals") or {}
    lines = [
        "## Site map", "",
        f"- Rendering: **{site.get('rendering')}** · framework: {', '.join(site.get('framework') or []) or 'unknown'}",
        f"- Signals: server HTML text {signals.get('server_text_bytes', 0)} B vs DOM text "
        f"{signals.get('dom_text_bytes', 0)} B · {signals.get('xhr_count', 0)} API calls",
        "",
        "| page | title | requests | links | forms | buttons |",
        "|---|---|---|---|---|---|",
    ]
    for page in (site.get("pages") or [])[:20]:
        structure = page.get("structure") or {}
        lines.append(f"| `{page.get('url')}` | {(page.get('title') or '')[:60]} | "
                     f"{page.get('requests', 0)} | {page.get('links', 0)} | "
                     f"{structure.get('forms', 0)} | {structure.get('buttons', 0)} |")
    flows = site.get("flows") or []
    if flows:
        lines += ["", "### Flows", ""]
        for flow in flows[:20]:
            where = flow.get("action") or flow.get("selector") or flow.get("page")
            fields = ", ".join(f for f in flow.get("fields") or [] if f)
            lines.append(f"- **{flow.get('kind')}** on `{flow.get('page')}` → `{where}`"
                         f"{(' (fields: ' + fields + ')') if fields else ''} — `{flow.get('evidence')}`")
    return lines + [""]


def _graph_section(graph):
    stats = graph.get("stats") or {}
    lines = [
        "## Flow graph", "",
        f"- {stats.get('nodes', 0)} nodes · {stats.get('edges', 0)} value-dependency edges · "
        f"{stats.get('orphans', 0)} orphan requests",
        "",
    ]
    edges = graph.get("edges") or []
    if edges:
        lines += ["| from | to | value | confidence |", "|---|---|---|---|"]
        for edge in edges[:25]:
            lines.append(f"| `{edge['from']}` | `{edge['to']}` | "
                         f"`{edge['from_field']}` → `{edge['to_field']}` | {edge['confidence']} |")
        if len(edges) > 25:
            lines.append(f"| … | | (+{len(edges) - 25} edges in graph.json) | |")
        lines.append("")
    trigger_rows = []
    for node in graph.get("nodes") or []:
        for trigger in (node.get("triggers") or [])[:2]:
            selector = trigger.get("selector") or "-"
            trigger_rows.append(f"- **{node['id']}**: {trigger.get('kind')} "
                                f"`{selector}` ×{trigger.get('count')} ({trigger.get('confidence')})")
    if trigger_rows:
        lines += ["### Triggers", ""] + trigger_rows[:30] + [""]
    if graph.get("orphans"):
        lines += ["### Orphans", ""]
        for orphan in (graph.get("orphans") or [])[:10]:
            lines.append(f"- `{orphan['endpoint']}` seq {orphan['seq']} — {orphan.get('reason')}")
        lines.append("")
    return lines


def _static_section(static):
    stats = static.get("stats") or {}
    lines = ["## Static analysis", "",
             f"- {stats.get('bundles', 0)} bundles · {stats.get('candidates', 0)} candidates: "
             f"{stats.get('observed', 0)} observed, {stats.get('static_only', 0)} static-only (unconfirmed), "
             f"{stats.get('false_positive', 0)} false positives", ""]
    static_only = [item for item in static.get("candidates") or []
                   if item["classification"] == "static_only"]
    if static_only:
        lines += ["| candidate | kind | why unconfirmed |", "|---|---|---|"]
        for item in static_only[:20]:
            lines.append(f"| `{item['value'][:80]}` | {item['kind']} | {item['reason']} |")
        if len(static_only) > 20:
            lines.append(f"| … | | (+{len(static_only) - 20} in static.json) |")
        lines.append("")
    return lines


def readme_source(endpoints, meta, site=None, graph=None, static=None):
    mode = meta.get("mode", "spec")
    shown = [e for e in endpoints if not e.get("external")]
    lines = [
        f"# API map — {meta.get('title') or 'API'}",
        "",
        f"Generated by **rea-web** on {meta['generated_at']} from `{meta['source']}` "
        f"({'declared by an OpenAPI document' if mode == 'spec' else 'observed in browser traffic'}).",
        "",
        f"- **{len(shown)} endpoints** · base URL `{meta.get('base_url')}`",
        "- Client: [`client.py`](client.py) · Map: [`map.json`](map.json) · OpenAPI: [`openapi.json`](openapi.json) "
        "· Evidence: [`evidence/`](evidence/)",
    ]
    if meta.get("version"):
        lines.append(f"- API version: {meta['version']}")
    if meta.get("description"):
        lines += ["", meta["description"]]
    cls = client_name(meta)
    lines += ["", "## Quick start", "", "```python", "from client import " + cls + "Client",
              "api = " + cls + "Client()  # token=\"...\" or headers={\"X-API-Key\": \"...\"}",
              "```", ""]
    if meta.get("auth"):
        lines += [f"Auth declared/observed: {meta['auth']}. The client sends `token` as a Bearer header; "
                  "pass API keys or other headers via `headers=`.", ""]
    if site:
        lines += _site_section(site)
    if graph:
        lines += _graph_section(graph)
    if static:
        lines += _static_section(static)
    websockets = [e for e in shown if e.get("kind") == "websocket"]
    if websockets:
        lines += ["## WebSockets", ""]
        for ep in websockets:
            frames = ep.get("frames") or {}
            lines.append(f"- **`WS {ep['path']}`** — sent {frames.get('sent', 0)} / received "
                         f"{frames.get('received', 0)} frames")
            refs = " · ".join(f"`{e['ref']}`" for e in ep.get("evidence", []))
            lines.append(f"  Sent: `{fmt((ep.get('body') or {}).get('schema'), max_depth=2)}` · "
                         f"Received: `{fmt((ep.get('response') or {}).get('schema'), max_depth=2)}` · {refs}")
        lines.append("")
    lines += ["## Endpoints", ""]
    for ep in shown:
        if ep.get("kind") == "websocket":
            continue
        if ep.get("kind") == "graphql":
            gql = ep.get("graphql") or {}
            lines.append(f"### GraphQL {gql.get('type', 'query')} `{gql.get('operation')}` (`POST {ep['path']}`)")
        else:
            lines.append(f"### `{ep['method']} {ep['path']}`")
        meta_line = _endpoint_meta(ep)
        if meta_line:
            lines += ["", meta_line]
        if ep.get("summary"):
            lines.append("")
            lines.append(ep["summary"])
        table = _param_table(ep)
        if table:
            lines += ["", table]
        if ep.get("body"):
            body = ep["body"]
            lines += ["", f"**Request body** ({body.get('content_type')}, "
                          f"{'required' if body.get('required') else 'optional'}): "
                          f"`{fmt(body.get('schema'), max_depth=2)}`"]
        if ep.get("response"):
            response = ep["response"]
            schema = fmt(response.get("schema"), max_depth=2) if response.get("schema") else "no schema"
            lines += ["", f"**Response {response.get('status')}**: `{schema}`"]
        for error in ep.get("errors") or []:
            lines += ["", f"**Observed error {error.get('status')}**: `{fmt(error.get('schema'), max_depth=2)}`"]
        lines += ["", "```python", _example(ep), "```", ""]
        refs = " · ".join(f"`{e['ref']}`" for e in ep.get("evidence", []))
        lines.append(f"Evidence: {refs} ({ep.get('confidence', 'declared')})")
        lines.append("")
    lines += ["## Limitations", ""]
    if mode == "spec":
        lines.append("- Endpoints and schemas come from the OpenAPI document; untested runtime behavior is not implied.")
    else:
        lines.append("- Observed traffic comes from loading/scrolling the visited pages; flows that need "
                     "clicks, form submits, or login were not exercised (see Site map flows).")
        lines.append("- Formats are inferred from observed samples and may be incomplete; optional fields "
                     "not present in the capture are absent.")
    lines += ["- Secrets (authorization headers, cookies, token-like params) are redacted in `evidence/`.",
              "- No live calls are made by `rea-web` itself unless you pass `--smoke`.", ""]
    return "\n".join(lines)


def openapi_doc(endpoints, meta):
    """Build an OpenAPI 3.0 document from the observed/declared map."""
    doc = {
        "openapi": "3.0.3",
        "info": {
            "title": meta.get("title") or "API",
            "version": str(meta.get("version") or "observed"),
            "description": (meta.get("description") or "")[:1000],
        },
        "paths": {},
    }
    if meta.get("base_url"):
        doc["servers"] = [{"url": meta["base_url"]}]
    for ep in endpoints:
        if ep.get("external") or ep.get("kind") == "websocket":
            continue
        path, method = ep["path"], ep["method"].lower()
        operation = {
            "operationId": ep["id"],
            "responses": {},
            "x-reaweb-evidence": [e["ref"] for e in ep.get("evidence", [])],
            "x-reaweb-confidence": ep.get("confidence"),
        }
        if ep.get("summary"):
            operation["summary"] = ep["summary"]
        params = []
        for p in ep.get("params", []):
            entry = {"name": p["name"], "in": p["in"], "required": p["required"],
                     "schema": to_openapi({"type": p["type"]})}
            if p.get("example") is not None:
                entry["example"] = p["example"]
            params.append(entry)
        if params:
            operation["parameters"] = params
        if ep.get("kind") == "graphql":
            gql = ep.get("graphql") or {}
            operation["x-graphql-operation"] = {"type": gql.get("type"), "name": gql.get("operation")}
            operation["requestBody"] = {
                "required": True,
                "content": {"application/json": {"schema": {
                    "type": "object",
                    "properties": {"query": {"type": "string"}, "variables": {"type": "object"}},
                    "required": ["query"],
                }}},
            }
        elif ep.get("body"):
            body = ep["body"]
            operation["requestBody"] = {
                "required": bool(body.get("required")),
                "content": {body.get("content_type") or "application/json": {
                    "schema": to_openapi(body.get("schema"))}},
            }
        response = ep.get("response") or {}
        status = str(response.get("status") or "default")
        entry = {"description": f"{ep.get('confidence', 'observed')} response"}
        if response.get("schema"):
            entry["content"] = {"application/json": {"schema": to_openapi(response["schema"])}}
        operation["responses"][status] = entry
        if ep.get("auth"):
            operation["security"] = [{"bearerAuth": []}]
        existing = doc["paths"].setdefault(path, {}).get(method)
        if existing and ep.get("kind") == "graphql":
            existing.setdefault("x-graphql-operations", []).append({
                "operation": (ep.get("graphql") or {}).get("operation"),
                "query": (ep.get("graphql") or {}).get("query"),
                "evidence": [e["ref"] for e in ep.get("evidence", [])],
            })
            continue
        doc["paths"][path][method] = operation
    if any(ep.get("auth") == "bearer" for ep in endpoints):
        doc["components"] = {"securitySchemes": {
            "bearerAuth": {"type": "http", "scheme": "bearer", "bearerFormat": "JWT"}}}
    return doc


def write_outputs(outdir, endpoints, meta, spec=None, capture_doc=None, static=None):
    out = Path(outdir)
    (out / "evidence").mkdir(parents=True, exist_ok=True)
    evidence = {}
    graph = None
    if capture_doc and capture_doc.get("transactions"):
        graph = build_graph(endpoints, capture_doc["transactions"], capture_doc.get("events") or [])
        events = capture_doc.get("events") or []
        if events:
            (out / "evidence" / "events.json").write_text(
                json.dumps({"events": events}, indent=2, ensure_ascii=False), encoding="utf-8"
            )
            evidence["events"] = "evidence/events.json"
    if spec:
        raw = spec["raw"]
        doc = spec["doc"]
        try:
            text = json.dumps(doc, indent=2, ensure_ascii=False)
        except (TypeError, ValueError):
            text = raw.decode("utf-8", "replace")
        (out / "evidence" / "spec.json").write_text(text, encoding="utf-8")
        evidence["spec"] = "evidence/spec.json"
    site = (capture_doc or {}).get("site")
    if capture_doc:
        capture_doc = {**capture_doc, "transactions": capture_doc.get("transactions", [])}
        (out / "evidence" / "network.json").write_text(
            json.dumps(capture_doc, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        evidence["network"] = "evidence/network.json"
    if site:
        (out / "evidence" / "site.json").write_text(
            json.dumps(site, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        evidence["site"] = "evidence/site.json"

    mapdoc = {
        "generated_at": meta["generated_at"],
        "generator": "rea-web/0.1",
        "source": meta["source"],
        "mode": meta["mode"],
        "title": meta.get("title"),
        "version": meta.get("version"),
        "description": meta.get("description"),
        "base_url": meta.get("base_url"),
        "auth": meta.get("auth"),
        "site": site,
        "graph": (graph or {}).get("stats"),
        "static": (static or {}).get("stats"),
        "endpoints": endpoints,
        "evidence": evidence,
        "limitations": meta.get("limitations", []),
    }
    (out / "map.json").write_text(json.dumps(mapdoc, indent=2, ensure_ascii=False), encoding="utf-8")
    (out / "openapi.json").write_text(json.dumps(openapi_doc(endpoints, meta), indent=2, ensure_ascii=False), encoding="utf-8")
    if graph:
        (out / "graph.json").write_text(json.dumps(graph, indent=2, ensure_ascii=False), encoding="utf-8")
    if static:
        (out / "static.json").write_text(json.dumps(static, indent=2, ensure_ascii=False), encoding="utf-8")
    (out / "client.py").write_text(client_source(endpoints, meta), encoding="utf-8")
    (out / "README.md").write_text(
        readme_source(endpoints, meta, site=site, graph=graph, static=static), encoding="utf-8")
    shown = [e for e in endpoints if not e.get("external")]
    return {
        "outdir": str(out),
        "mode": meta["mode"],
        "title": meta.get("title"),
        "base_url": meta.get("base_url"),
        "endpoints": len(shown),
        "websockets": sum(1 for e in shown if e.get("kind") == "websocket"),
        "graphql": sum(1 for e in shown if e.get("kind") == "graphql"),
        "rendering": (site or {}).get("rendering"),
        "flows": len((site or {}).get("flows") or []),
        "graph_edges": (graph or {}).get("stats", {}).get("edges", 0),
        "graph_orphans": (graph or {}).get("stats", {}).get("orphans", 0),
        "static_candidates": (static or {}).get("stats", {}).get("candidates", 0),
        "static_only": (static or {}).get("stats", {}).get("static_only", 0),
        "files": ["map.json", "openapi.json", "client.py", "README.md"]
                 + (["graph.json"] if graph else []) + (["static.json"] if static else [])
                 + list(evidence.values()),
    }
